@startuml

class Patient {
  + Id : string
  + Name : string
  + Symptoms : string
}

class Doctor {
  + Id : string
  + Name : string
  + Specialization : string
}

class HeadDoctor {
  + Id : string
  + Name : string
}

class Illness {
  + Id : string
  + Name : string
  + PriorityScore : PriorityScore
}

enum PriorityScore {
  High
  Low
}

class Diagnosis {
  + Id : string
  + Description : string
  + IsApproved : boolean
}

class Treatment {
  + Id : string
  + Description : string
  + CurrentStage : int
}

class ConsentForm {
  + Id : string
  + SignatureDate : date
  + IsActive : boolean
}

class TreatmentDatabase {
  + Id : string
  + LastUpdated : datetime
}

Doctor "1..*" -- "0..*" Patient : treats
Doctor "1" -- "0..*" Diagnosis : makes
HeadDoctor --|> Doctor
HeadDoctor "1" -- "0..*" Diagnosis : approves
Patient "1" -- "0..*" Diagnosis : receives
Diagnosis "1" -- "0..*" Treatment : leadsTo
Illness "1" -- "0..*" Diagnosis : identifiedAs
Illness "1" -- "0..*" Treatment : affects
TreatmentDatabase "1" -- "0..*" Treatment : contains
Patient "1" -- "0..*" ConsentForm : signs
ConsentForm "1" -- "0..*" Treatment : permitsUpgrade

@enduml

